def add(sub,b,title,why,facts,static,analysis,trap,mains,src='PRS',day=0,ap=False,p='P1',precision=None):
 J.append(dict(id=f'E14-2607-{len(J)+1:03}',date=f'2026-07-{day:02}' if day else '2026-07-31',date_precision=precision or ('day' if day else 'month'),subject=sub,block=b,title=title,why=why,facts=facts.split('|'),static_link=static,analysis=analysis.split('|'),trap=trap,mains=mains,priority=p,ap=ap,sources=['E14-'+x for x in src.split(',')],status='Historical July-indexed selected research; drafts, reporting dates and thematic supplements explicitly distinguished. Not latest-law or implementation certification.',checked='2026-11-07',evidence_access='Source-access registry records the passages actually read and primary/secondary limits. Static connections, analysis and exam prompts are original guidance.'))
add('Polity & Governance','01 · Examination integrity','Public examinations Bill: deterrence needs investigative capacity','PRS records introduction on 27 July and passage by Parliament on 30 July. Assent and commencement were not independently established in this batch.','The amendment Bill raises the proposed punishment for use of unfair means to five–ten years and a fine up to ₹50 lakh.|Service-provider penalties rise to ₹5 crore, with debarment extended from four to eight years.|It provides for a central Special Task Force, two-month investigation, designated Sessions fast-track courts and a three-month trial target after chargesheet.','The 2024 central Act covers specified examination authorities; this is not proof every school test or every AP recruitment examination automatically falls within identical jurisdiction.','Paper leaks undermine equality of opportunity, public trust and the fiscal investment of candidates.|Secure printing, encrypted delivery, vendor due diligence and independent incident logs complement punishment; rushed investigation can weaken evidence and fair trial.|For APPSC preparation, distinguish national legislation from the state recruitment authority’s rules and actual notification.','Parliamentary passage is not itself verified commencement. Timelines and higher maximum fines do not prove faster conviction.','Evaluate a prevention–investigation–trial framework for public examination integrity.',day=30)
add('Polity & Governance','02 · Judicial capacity','Supreme Court strength: replacement Bill and the CJI denominator','A July Bill seeks to replace the 16 May Ordinance expanding the sanctioned bench.','The change is from 33 to 37 judges excluding the Chief Justice of India.|Including the CJI, the corresponding totals are 34 and 38.|A sanctioned position, a filled vacancy and a functioning bench are separate measures of judicial capacity.','Article 124 permits Parliament by law to prescribe the number beyond the constitutional minimum; an ordinary strength amendment is not a constitutional amendment. Article 123 ordinances require subsequent parliamentary handling.','More judges may improve disposal, but appointment delays, case management and constitution-bench scheduling matter.|Measure age-wise pendency, time to hearing and reasoned disposal rather than assuming four sanctioned posts eliminate backlog.|Read this alongside the May Ordinance note as a legislative sequence, not a second independent increase.','Do not add four judges in May and another four in July merely because two instruments address the same change.','Why must judicial-capacity reform combine bench strength with procedural reform?',p='P2')
add('Polity & Governance','03 · Legal profession','Draft Advocates reform: regulated entry and representative institutions','The law ministry released a consultation draft amending the Advocates Act, 1961.','The draft proposes registration of foreign lawyers/firms with the BCI or a State Bar Council, with practice limited to international commercial arbitration.|It does not propose unrestricted appearance by foreign lawyers in Indian courts and tribunals.|The proposals include women’s reserved elected seats, welfare/social-security instruments and an election-dispute tribunal.','BCI, State Bar Councils and courts perform different regulatory/adjudicatory functions; professional self-regulation remains subject to law and constitutional review.','Arbitration expertise and reciprocity may attract international business while protectionist barriers can limit competition.|Representation of women requires fair election design and professional pathways, not only reserved seat totals.|Transparent registration, conflict rules, client protection and a clear domestic-practice boundary are more useful than treating foreign entry as entirely open or entirely prohibited.','These are draft proposals, not proved operative rights, final seat allocations or a licence for every foreign advocate.','How can professional regulation balance global legal services with accountability and inclusion?',p='P2')
add('Economy','01 · MSME liquidity and classification','MSME amendment Bill: thresholds, invoices and proportionate enforcement','A Bill introduced in Rajya Sabha proposes changes to the 2006 development framework.','It would empower the Union to notify classification thresholds using investment and turnover rather than retaining statutory investment figures.|It would require CPSE settlement of procurement invoices from MSMEs through TReDS.|Selected reporting/information defaults move toward warnings and graduated monetary penalties.','TReDS is an RBI-regulated receivables-financing platform; discounting converts an accepted invoice into earlier liquidity, not a budgetary grant or automatic debt forgiveness.','Adjustable thresholds can accommodate inflation and business growth but need predictable notice and consultation.|Invoice acceptance delays can defeat platform financing even when registration numbers rise.|AP supplier-development programmes should track payment days, buyer acceptance, discount costs and access of small firms rather than only platform enrolment.','Do not quote a proposed statutory threshold mechanism as a new notified turnover limit or call introduction enactment.','Assess whether TReDS mandates can solve delayed payments to MSMEs.')
add('Economy','01 · MSME liquidity and classification','CPSE TReDS directive is distinct from the pending MSME Bill','PRS separately records an executive mandate for CPSE use of TReDS alongside the legislative proposal.','CPSEs are directed to settle invoices through TReDS in the reviewed account.|Auditors are to certify registration with at least one TReDS platform.|The contemporaneous Bill also addresses invoice settlement, but its legal stage must be recorded separately.','Executive instructions, statutory amendments, platform registration and actual invoice financing are different layers of compliance; they should not be merged into one claimed enacted reform.','Government buyers can provide a reliable anchor for small suppliers, provided receivables are promptly acknowledged.|Audit should test eligible invoice coverage, disputes and days to payment, not merely a certificate of registration.|Avoid double-counting this directive and the Bill as two sets of realised benefits to the same firm.','The original directive was not independently read; this note is PRS-based and does not certify applicability to every state PSU or private buyer.','Distinguish formal platform compliance from effective working-capital access.',p='P2')
add('Society & Welfare','01 · Rural employment transition','Rural-employment payments: DBT, allowance and lawful exceptions','Rules notified on 1 July prescribe the manner of wage and unemployment-allowance payment.','Payments go directly into the beneficiary’s bank or post-office account through DBT.|Cash is ordinarily prohibited, but the Union may provide an exemption by order in extraordinary circumstances.|Unemployment allowance is paid by the respective state/UT under the specified fund-flow mechanism.','A wage for work and unemployment allowance for a qualifying failure to provide work are different entitlements. Digital routing is not a substitute for establishing the underlying entitlement.','Electronic audit trails can improve transparency, but failed authentication, dormant accounts and distance to banking points can cause exclusion.|Publish payment rejection reasons, accessible assistance and time-bound correction rather than treating a generated order as successful credit.|For AP, social audit should compare muster rolls, payment orders and actual worker receipts across tribal and remote areas.','Neither unconditional cash payment nor an absolute no-exceptions cash ban accurately describes the rule. DBT does not mean the Union pays every allowance.','How can digital payment rules preserve both accountability and effective worker access?',src='PRS,WAGES',day=1)
add('Society & Welfare','01 · Rural employment transition','Transition rules: old liabilities and balance-day entitlement','The 1 July rules preserve an accounting and entitlement bridge from MGNREGS.','States verify liabilities existing up to 30 June 2026 and settle admissible claims.|Audited utilisation certificates are due within 180 days, with a possible further 90-day extension by the Union.|Continuing works, verified records and eligible cards carry forward; days already availed are adjusted against the relevant financial-year guarantee.','A statutory transition does not extinguish verified arrears or reset a household’s financial-year work history to zero. Assets and records also require an accountable transfer.','Reconcile old work codes, outstanding wages, material dues and asset registers to prevent double payment or disappearance of liabilities.|A 180-day accounting deadline is not a universal wage-payment grace period.|AP implementation should offer a worker-facing statement of days used, balance days and pending wages; aggregate expenditure cannot establish an individual household’s entitlement.','Do not promise a fresh full annual entitlement in addition to days already used, or treat every old claimed liability as automatically admissible.',src='PRS,TRANSITION',day=1,mains='Design an inclusive and auditable transition between rural-employment regimes.')
add('Science & Technology','01 · Electronics value chains','Semicon 2.0: six pillars beyond the fabrication plant','The Cabinet approved an ecosystem programme on 15 July with ₹1,27,500 crore outlay.','The six pillars cover design/IP, machines/materials, fabs, ATMP/OSAT, advanced R&D and talent.|ATMP means assembly, testing, marking and packaging; OSAT refers to outsourced semiconductor assembly and test.|The release distinguishes twelve approved manufacturing units under the earlier phase from three that had begun commercial production.','Chip design, wafer fabrication and packaging are complementary but technologically different activities. An approved fab is not the same as a commissioned high-yield production line.','Supply-chain resilience needs gases, chemicals, equipment servicing and skilled clean-room operation, not simply subsidised buildings.|Assess water and electricity demand, environmental controls, technology choice and long-term unit economics.|For AP electronics clusters, supplier capability and training partnerships can create value even without a leading-edge fab; no new AP fab approval is inferred here.','Do not classify every packaging unit as a silicon wafer fab or count approved investment as completed production.','How can India move from semiconductor incentives to a durable industrial ecosystem?',src='SEMICON,PRS',day=15)
add('Economy','02 · Manufacturing incentives','Mobile Phone Manufacturing Scheme: sales, sourcing and design','The Cabinet approved ₹62,500 crore for FY2026–27 to FY2030–31.','Eligible manufacturing sales receive differentiated incentives of 2.25%–5%.|Additional support up to 1.5% is linked to domestic sourcing of key components/sub-assemblies.|A further 3% design/R&D incentive supports Indian brands; the release’s production and job figures are expectations.','Gross assembly value, exports and domestic value addition are not interchangeable. A domestically assembled phone can contain imported high-value components and foreign-owned intellectual property.','Incentive design should reward learning, local supplier quality and commercially sustainable R&D rather than relabelling imported inputs.|Monitor additional exports, subsidy per incremental job and value added net of imported content.|AP can connect electronics training and component suppliers to national value chains, but an approval does not establish state-level allocations or realised employment.','Do not automatically add all headline rates for every firm; eligibility conditions and differentiated support matter.','Evaluate output-linked incentives against domestic value addition and technological ownership.',src='MOBILE,PRS',day=15)
add('Polity & Governance','04 · National symbols and civil registration','National song Bill: intentional disruption versus compulsory singing','PRS records parliamentary passage of an amendment to the National Honour Act.','The Bill extends specified protections concerning singing of the national anthem to Vande Mataram, the national song.|The existing offence concerns intentionally preventing singing or causing disturbance to an assembly engaged in singing.|The reviewed penalty framework includes imprisonment up to three years, fine or both, with a higher minimum for repeat conviction.','Jana Gana Mana and Vande Mataram have distinct designations. Penal provisions must be interpreted through their precise conduct and intent elements, not expanded from a headline.','National-symbol protection raises questions of civic respect, proportional enforcement and freedoms of conscience and expression.|Clear public guidance and reasoned enforcement reduce arbitrary use.|A study answer should distinguish preventing an assembly from singing from merely declining personally to sing; the reviewed summary does not prove a new universal compulsory-singing duty.','Parliamentary passage alone does not establish assent/commencement, and protection of the song does not rename it the national anthem.','How should national-symbol legislation be assessed within constitutional freedoms?',p='P2')
add('Polity & Governance','04 · National symbols and civil registration','Births and deaths Bill: delayed registration and judicial verification','Introduced on 29 July, the Bill passed Lok Sabha on 31 July in the reviewed account.','The reviewed existing framework requires an authorised magistrate’s order for registration after a year.|The Bill proposes that delays exceeding two years require an order only from a Judicial Magistrate First Class.|Verification of correctness and prescribed fees are part of the delayed-registration setting.','Registration establishes an official vital-event record; it is not by itself citizenship adjudication. Executive and judicial magistrates are different authorities.','Judicial scrutiny may deter fraudulent records but can increase travel, cost and delay for poor households.|Simpler timely registration, hospital linkage, mobile assistance and reliable document checks can reduce the need for delayed proceedings.|For AP, evaluate remote birth access and appeal support rather than assuming computerisation removes every documentation barrier.','Lok Sabha passage is not passage by both Houses. Do not turn a delay threshold into an assertion that all births can lawfully remain unregistered for two years.','Balance record integrity with universal and timely civil registration.',day=31)
add('Economy','03 · Financial regulation','Draft foreign-investment rules: a proposed 10% distinction','RBI invited comments on a proposed replacement of the 2019 Non-debt Instruments Rules.','The draft defines FDI as foreign investment of 10% or more in company/LLP equity and FPI as below 10%.|It expands and reorganises eligible-entity and equity definitions.|RBI administers operational/payment/reporting matters, while DPIIT interprets foreign-investment policy; comments were invited until 31 August.','Under the reviewed 2019 baseline, foreign equity in an unlisted Indian company is FDI irrespective of percentage; listed-company classification uses the 10% distinction. Draft and baseline must not be mixed.','Consolidation can reduce interpretive uncertainty but requires clarity on sector caps, indirect investment and transition.|A numerical classification is not equivalent to unrestricted automatic-route permission or control; other legal conditions remain relevant.|AP investment-promotion answers should distinguish policy facilitation from legal approval and beneficial-ownership checks.','The hosted PDF has a blank notification date and is a draft, not proof the 2019 Rules were superseded in July.','Why do foreign-investment reforms need precise definitions and institutional boundaries?',src='FEMA,PRS')
add('Economy','03 · Financial regulation','Portfolio-management consultation: mutual-fund-only entry','SEBI proposed a separate framework for portfolio managers investing only in mutual funds.','For that proposed category, minimum client investment would fall from ₹50 lakh to ₹25 lakh.|Applicant net worth would fall from ₹5 crore to ₹2 crore.|The paper also discusses demat portability, expanded investment options and compliance changes; comments were invited until 13 August.','A PMS client mandate, a mutual-fund unit holding and the manager’s own regulatory net worth are different concepts; investor ticket size is not the same as fund-manager capital.','A lower entry threshold can widen access but adds an advisory/fee layer over mutual funds.|Disclosure should compare total costs, suitability, conflicts and actual service rather than implying higher fees guarantee superior returns.|Portability can reduce switching costs, while investor protection needs clear asset custody and transfer processes.','These reduced thresholds concern the proposed mutual-fund-only category, not every PMS. A consultation is not a final relaxation.','Assess competition, suitability and cost transparency in managed investment services.',p='P2')
add('Economy','03 · Financial regulation','Insurance regulations: actuarial separation and protected policyholder funds','PRS reviews notified IRDAI regulations implementing the 2025 insurance-law amendments.','Reinsurers must appoint separate actuaries for life and general reinsurance.|A framework addresses amalgamation/transfer involving non-insurance and insurance businesses.|Policyholder funds cannot be used to meet liabilities arising from such amalgamation; the transferee board must consider adverse impact on policyholders.','An actuary assesses long-term financial risks; actuarial valuation is distinct from a statutory financial audit. Policyholder money must not be confused with shareholders’ discretionary capital.','Business consolidation can improve scale while creating related-party and asset-transfer risks.|Board accountability, independent valuation and ring-fencing should be tested against actual liabilities.|The education/protection fund supports awareness, grievance infrastructure and unclaimed-amount recovery systems; its existence is not a promise to reimburse every claim.','Notified rules are not a completed merger, and the reviewed summaries do not establish every insurer’s compliance.','Explain why insurance-sector liberalisation requires stronger governance of policyholder funds.',p='P2')
add('Economy','03 · Financial regulation','Securities Markets Code scrutiny: bounded delegation and appeal','The Finance Standing Committee examined the proposed consolidation of three securities laws.','The proposed Code would consolidate the SCRA1956, SEBI Act1992 and Depositories Act1996.|The Committee sought clearer limits on regulation-making and delegation to market infrastructure institutions.|It recommended redrafting overlapping civil/criminal defaults and allowing appeals against all SEBI/adjudicating-officer orders to SAT.','Parliament sets essential legislative policy; delegated regulation supplies details within a lawful framework. Exchanges/depositories may themselves face conflicts when exercising delegated supervisory functions.','Consolidation can simplify compliance but broad discretion without reasons, review and accountability risks regulatory uncertainty.|Appeal design should preserve urgent protective action while providing timely independent correction.|For an answer, trace rule-maker, delegated supervisor, enforcement authority and appellate body instead of treating all of them as SEBI.','Committee recommendations are not enacted clauses, and a proposed right of appeal does not automatically suspend every regulatory order.','Can a consolidated market code improve both regulatory agility and the rule of law?')
add('Economy','04 · Maritime and rail logistics','Major-port waterfront policy: renewal is not a free transfer','The Cabinet revised the 2016 dedicated-facility policy, according to PRS.','Existing agreements may be renewed/extended for up to 30 years without a fresh tender under the revised policy.|Renewal pricing uses prevailing market rate or existing payable revenue, whichever is higher.|Specified government entities may receive allotments without competitive bidding at notified floor prices.','Major-port governance under the Union is distinct from state-controlled non-major ports. A lease/concession, land ownership and private cargo operations are different legal relationships.','Continuity can support sunk industrial investment, but independent valuation and transparent eligibility protect public revenue.|Exemptions from bidding require published reasons, performance conditions and conflict controls.|For Visakhapatnam and AP port policy, first identify the port’s legal category; do not apply Union-major-port concessions to every coastal project.','No fresh tender does not mean zero price, permanent ownership, or unconditional eligibility of every company.','How can port-land allocation balance long-term investment and competitive neutrality?',p='P2')
add('Economy','04 · Maritime and rail logistics','Railway reforms: contract risk, specialised wagons and fly ash','PRS records eight railway reforms addressing contractors, freight and skilling.','Performance security is to be furnished at contract commencement instead of recovered from running bills.|A proposed eligibility restriction addresses pending litigation exceeding 50% of contractor net worth.|Industry/designers may propose specialised wagons, while ISO-standard containers are envisaged for fly-ash transport.','Performance security protects execution; it is not a penalty for proved wrongdoing. Pending litigation is exposure, not an adjudicated liability or automatic evidence of guilt.','Earlier security may improve assurance but can strain contractor liquidity and reduce competition.|Special-purpose freight equipment should meet safety, interoperability and maintenance standards.|AP thermal-station ash logistics offers an application: covered/containerised movement can reduce dust, but reuse requires suitable quality and economic destinations.','Do not infer every open wagon was banned immediately or that a pending case establishes contractor guilt.','Assess risk allocation and environmental performance in railway freight reform.',p='P2')
add('Agriculture','01 · Farm inputs and income','Urea investment policy: separating fixed and variable costs','The July review records CCEA approval of the National Investment Policy for Urea2026.','The previous 2012 investment-policy window ended in 2019.|The new framework separates fixed and variable costs and provides a return-on-equity band of 12%–16%.|The reviewed account provides for conversion of fixed costs into rupees after four years using prevailing exchange rates.','Investment support, producer cost recovery, fertiliser subsidy and the farmer’s retail price are different mechanisms. A return band is not a guaranteed interest rate for ordinary savers.','Additional domestic output may reduce import vulnerability but feedstock cost, gas availability and plant efficiency remain important.|Nutrient imbalance and water/soil effects require extension and balanced fertilisation, not only more urea capacity.|Do not equate policy approval with commissioned production or infer a particular AP plant was sanctioned.','The original policy text was not independently inspected; the note does not establish a new retail urea price.','Can fertiliser investment reform improve security without deepening nutrient imbalance?',p='P2')
add('Agriculture','01 · Farm inputs and income','PM-KISAN continuation: ₹3.15 lakh crore, not a benefit increase','The Cabinet approved continuation through FY2030–31 on 31 July.','The exact approved outlay is ₹3.15 lakh crore for FY2026–27 to FY2030–31.|Eligible landholding farmer families continue to receive ₹6,000 annually in three equal instalments.|Digital verification and DBT are delivery mechanisms; the release does not announce ₹6,000 per individual member or per instalment.','Income support differs from crop insurance, minimum support prices and credit waivers. Landholding-based eligibility can differ from the population actually cultivating the land.','Predictable transfers can finance seasonal inputs but nominal benefits may lose purchasing power.|AP analysis should examine tenant farmers, women’s land titles, mutation errors and prompt correction of rejected transfers.|Reported beneficiary feedback and simultaneous production growth do not by themselves establish a causal programme effect without evaluation design.','PRS rounds the outlay to ₹3.2 lakh crore; use the primary ₹3.15 lakh crore. Continuation is not a newly doubled annual benefit.','Assess income support with attention to adequacy, eligibility and delivery reliability.',src='PMK,PRS',day=31)
add('Society & Welfare','02 · Food standards and distribution','Sugar labelling: committee recommendations and consumer comprehension','A parliamentary committee examined sugar content in packaged foods, including baby products.','Recommendations include a scientifically grounded sugar-level classification framework.|The Committee sought uniform labelling and age-relevant front-of-pack information for infant products.|It also recommended periodic scientific review and e-commerce monitoring of mislabelled products.','A nutrition label, a health claim and an enforceable food standard are different regulatory tools. Added sugar, total sugars and energy contribution are not identical measures.','Labels should help real purchasing decisions, including low-literacy consumers, rather than merely expand fine print.|Independent testing, online-market accountability and action against misleading claims complement design reform.|AP maternal/child-health programmes can use food-literacy counselling without assuming every packaged infant food is interchangeable or medically suitable.','The report is not itself a newly notified FSSAI sugar limit, and exact thresholds require the relevant final standard.','How can food labelling move from disclosure compliance to meaningful consumer protection?',p='P2')
add('Society & Welfare','02 · Food standards and distribution','PDS modernisation: authentication success is not food receipt','The Committee reviewed digitisation, portability and the technical database of the PDS.','PRS reports near-complete card digitisation, Aadhaar seeding and fair-price-shop automation.|The Committee sought inclusion of eligible left-out households and verification of suspect records.|It specifically flagged authentication problems among elderly people and manual labourers and recommended examining DBT pilots.','Deletion of a ration card does not automatically prove fraud, and a seeded Aadhaar number does not prove a household received its food entitlement. Administrative coverage is not nutritional adequacy.','Use exception handling, offline alternatives and grievance tracking to protect eligible beneficiaries.|Portability helps migrants only if entitlement visibility, shop stock and authentication all work together.|AP audits should sample actual receipts, denial reasons and time to correction, while retaining privacy safeguards for linked household data.','Do not treat all deleted cards as proven duplicate beneficiaries, or committee support for assessing pilots as a national cash-replacement order.','Design an inclusion-sensitive evaluation of digital PDS reform.')
add('Agriculture','02 · Procurement and food quality','Rice quality norms: July approval, KMS2027–28 distribution','The Cabinet revised permissible broken-grain content for welfare rice.','Raw-rice broken content is to fall from 25% to 10%.|For parboiled rice, the corresponding norm changes from 16% to 5%.|The reviewed decision schedules distribution of the revised grains from Kharif marketing season2027–28.','Broken-grain percentage concerns grain quality, not a household’s quantity entitlement. Raw and parboiled rice are different processing categories.','Better quality may improve acceptability, while mills and procurement agencies need segregation, testing and supply planning.|Assess recovery rates, storage, costs and the utilisation of rejected/broken grain, without assuming all broken rice is unsafe.|AP procurement answers should preserve the implementation season and distinguish food quality from the June draft AAY quantity formula.','Do not apply the new quality percentages to July2026 deliveries as if already universally implemented, or call this a cut in ration kilograms.','Examine implementation trade-offs in improving welfare-grain quality.',p='P2')
add('Environment','01 · Environmental rule of law','Retrospective EC judgment: narrow amnesty is not perpetual regularisation','On 29 July the Supreme Court distinguished the 2017 notification from the 2021 administrative OM.','The Court upheld the 2017 notification as narrowly tailored, time-bound delegated legislation.|It quashed the perpetual 2021 OM prospectively; an administrative instruction cannot supplant the EIA notification.|Existing ECs remain valid unless individually challenged; no further applications under the impugned instruments are to be entertained.','Prior EC remains the normative requirement. Delegated legislation, an administrative OM and the Court’s Article142 power are legally distinct sources of authority.','A limited transitional response must not incentivise starting projects illegally and seeking routine later approval.|Pending applications require the judgment’s specific directions, not automatic permission; individual ECs can still face lawful challenge.|For AP infrastructure, maintain project-specific permits and compliance chronology rather than assuming either every old clearance collapsed or every violation was forgiven.','The earlier May2025 ruling was recalled on review. Do not present that older rule as unchanged, or say all retrospective EC is categorically permitted.','Explain the judgment’s balance between prior clearance, legal hierarchy and transitional fairness.',src='COURT,PRS',day=29)
add('Environment','02 · Energy transition and resource security','PM Surya Sarovar: 5GW floating solar with two-hour storage','The Cabinet approved ₹5,070 crore for floating PV with co-located storage on 31 July.','The target is 5,000MW with at least two hours of storage, equivalent to 10,000MWh at that power scale.|Eligible projects receive ₹1 crore/MW after successful commissioning, plus preparatory support up to ₹50 lakh per project.|Sanctions run through FY2030–31 and disbursement through FY2032–33; approximately 700MW refers to existing floating PV, not all Indian solar.','MW measures power; MWh measures stored/delivered energy. Floating PV is not pumped storage, and a reservoir surface is not ecologically or socially vacant land.','Avoided land competition must be weighed against fisheries, water quality, evaporation, anchoring and reservoir operations.|Storage can shift energy in time but requires charging, round-trip-loss and safety analysis.|AP reservoirs need hydrological, bathymetric and community feasibility checks; nationwide eligibility does not imply a particular reservoir has been approved.','Do not mistake an assessed potential for commissioned capacity or equate the outlay with money already paid.','Evaluate floating solar through energy, water and livelihood safeguards.',src='SOLAR,PRS',day=31)
add('Economy','05 · Energy resources and industrial inputs','Samudra Manthan: exploration risk and the offshore value chain','The Cabinet approved the National Offshore Exploration Scheme on 31 July.','The Central Sector Scheme has an outlay of ₹84,084 crore through FY2030–31.|It supports seismic data, deep/ultra-deepwater exploration, scientific drilling and common evacuation infrastructure.|An Oil and Gas Manufacturing and Services Zone and capacity-building measures are included.','An exploratory resource estimate, discovered reserves, commercially recoverable reserves and actual production are different stages. Oil-equivalent units combine energy quantities, not identical physical volumes.','Public geological information can reduce information asymmetry and encourage investment, but unsuccessful wells remain a genuine risk.|Compare import-security gains with fiscal exposure, spill liability, marine impacts and energy-transition scenarios.|The Krishna–Godavari offshore setting is relevant to AP, without inferring a new state-specific reserve discovery or production allocation from this national approval.','Do not describe the expected reserve addition as oil already produced or confuse Samudra Manthan with the Deep Ocean Mission.','How should India evaluate strategic offshore exploration under uncertainty?',src='OFFSHORE,PRS',day=31)
add('Economy','05 · Energy resources and industrial inputs','Washed coal: beneficiation requires water and reject management','The Coal, Mines and Steel Committee reviewed infrastructure to augment washed-coal production.','Recommendations include modernised washeries and greater domestic washed-coking-coal blending.|Pithead washeries and rail-centric first-mile connectivity are proposed to reduce unnecessary haulage.|Water recycling, zero discharge and appropriate reject utilisation are central environmental recommendations.','Coal beneficiation reduces impurities/ash; it does not turn coal into a zero-carbon fuel. Coking-coal use in steelmaking differs from thermal-coal use in power generation.','Transporting less ash can lower freight burdens, but the removed material still needs safe management.|Compare yield, water use, quality consistency and lifecycle cost before assuming a washery always creates net gains.|AP steel and power procurement should identify coal grade and end use rather than substitute one category indiscriminately.','A Committee recommendation is not a commissioned washery or proof all clearance requirements have been relaxed.','Assess beneficiation as an industrial-efficiency and environmental-management intervention.',p='P2')
add('Economy','05 · Energy resources and industrial inputs','Steel self-reliance: specialty capability and raw-material security','A parliamentary report examined the roadmap for Made-in-India steel.','Recommendations cover specialty steel, technology transfer and stronger PLI support.|Rail-freight rationalisation and multimodal/last-mile links address logistics costs.|Faster operationalisation of iron-ore mines and beneficiation are proposed for raw-material security.','Crude-steel tonnage, specialty-grade capability and domestic technological ownership are separate dimensions of self-reliance. Beneficiation upgrades ore; it does not itself make finished steel.','Industrial policy should measure certified product quality, reliable orders and energy/material efficiency.|Mining expansion needs lawful clearances and community safeguards, while lower-carbon steel may face high electricity and capital requirements.|APPSC answers can connect Visakhapatnam’s industrial ecosystem with national issues without inventing a July plant-specific financial restructuring.','The report is a recommendation, not proof imports ended, a new state steel plant opened or all proposed PLI changes were notified.','Explain why steel competitiveness requires an ecosystem rather than capacity alone.',p='P2')
add('Society & Welfare','03 · Health-sector governance','Draft Pharmacy Commission: four boards and a common exit test','The health ministry released a draft intended to replace the Pharmacy Act1948.','It proposes a National Pharmacy Commission and four boards covering two education streams, assessment/rating and ethics/registration.|A proposed common exit test serves licensing, registration and postgraduate admission purposes.|State councils would be reconstituted within a year of commencement under the proposal.','Education accreditation, professional licensing and drug-product approval are not the same regulatory functions. A pharmacy professional’s registration is not a marketing authorisation for a medicine.','Clear competency standards can improve patient safety, but assessment quality and institutional independence matter.|State representation, transition arrangements and access for students from weaker institutions require scrutiny.|AP pharmacy education and manufacturing clusters need appropriately trained professionals; increasing seats alone does not assure safe dispensing or research capability.','This is a draft, not a newly operative mandatory examination date or proof existing registrations have expired.','Assess the proposed separation of educational, assessment and ethical functions.',p='P2')
add('Society & Welfare','03 · Health-sector governance','NMC consultation: readiness at application and corpus oversight','The draft new-medical-institutions amendment invited comments until 7 August.','Proposals revise eligible applicant categories and remove certain documents at the application stage.|The corpus undertaking would be addressed at approval, with a corpus requirement for existing colleges as well.|Completed infrastructure/statutory readiness is proposed at application; temporary work-in-progress arrangements would not suffice.','Application-stage documentation, substantive eligibility and final permission are different. Removing one certificate does not abolish all state permissions, land laws or clinical-quality requirements.','Capacity expansion must preserve patient load, faculty, clinical training and financial continuity.|Rigid rejection of incomplete applications can improve discipline but should be tested for transparent criteria and proportionate procedure.|AP should assess geographic access and the quality of teaching hospitals rather than equating a corporate applicant category with guaranteed affordable seats.','The original draft was not fully inspected, and the July consultation does not establish a final nationwide deregulation.','How can medical-education reform expand capacity without weakening quality?',p='P2')
add('Society & Welfare','03 · Health-sector governance','Drug-rule changes: targeted exemptions and risk-based quality','PRS reviews several July amendments concerning conventional and traditional-system medicines.','Specified formulations above 12% ethyl alcohol by volume in quantities exceeding 30ml lose a licensing exemption in the reviewed account.|ASU/homoeopathic manufacturing provisions address validity, product codes and labelling mechanisms.|Scientific shelf-life support, inspector qualifications and risk-based quality systems are among the changes.','An exemption from a particular licence is not a declaration of therapeutic efficacy or freedom from every safety rule. ASU, homoeopathic and other drugs cannot be treated as one undifferentiated legal category.','Permanent licence validity need not mean permanent compliance: inspections, quality assurance and lawful suspension remain important.|QR information helps only if accessible, reliable and backed by physical labelling essentials.|For AP, coordinate inspectors, laboratories and complaint channels rather than treating formal licence status as a guarantee that every batch is safe.','The primary instruments were not independently read; exact category-specific requirements and dates need the final Gazette, not a blanket summary.','Distinguish ease of compliance from dilution of medicine-quality oversight.',p='P2')
add('Awards & Sports','01 · Sports participation and athlete development','Khelo India revamp: development pathway, not a medal forecast','The Cabinet approved expanded Khelo India and ANSF support on 31 July.','Combined outlay is ₹36,441 crore for FY2026–27 to FY2030–31.|Feeder Schools, Utkrishta Vidyalayas and Emerging Khelo India Athletes strengthen the talent pathway.|A National Coach Accreditation Board and unified digital sports platform are envisaged alongside support for women, para-athletes and indigenous sports.','Grassroots participation, talent identification, high-performance training and competition exposure are different stages. ANSF assistance and Khelo India are not identical components even when the outlay is combined.','A pathway needs safe facilities, nutrition, trained coaches and school continuity, particularly for disadvantaged athletes.|Transparent selection, safeguarding, injury support and accessible para-sport opportunities prevent institutional expansion from reproducing exclusion.|AP should track regular participation and progression, not promise medals merely from sanctioned centres or digital registrations.','The end-year is 2030–31; PRS’s 2023–31 is a typo. An Olympic bid is not proof hosting rights were awarded.','Design an equitable athlete-development ecosystem from school to elite sport.',src='KHELO,PRS',day=31,p='P2')
add('Security','01 · Defence procurement and cyber resilience','Defence offsets: promised obligation versus transferred capability','The Public Accounts Committee reviewed management of defence offsets.','Offsets oblige foreign vendors to reverse-purchase, export, invest or support eligible domestic technology/R&D under contract terms.|Recommendations include broader capital-acquisition coverage and meeting 50% of obligations through FDI or technology transfer.|The Committee also sought clearer eligible technologies, deadlines and deterrents to non-compliance.','An offset credit, a contractual promise and independently absorbed technology are different measures. FDI value does not by itself prove domestic design capability.','Audit should test additionality, valuation, timeliness and whether local firms can maintain and improve the transferred technology.|Rigid targets can distort procurement if vendor capability and security needs are ignored.|For AP defence-industrial linkages, focus on certified suppliers and workforce capability rather than announcing state benefits from national recommendations.','These are Committee recommendations, not a universal newly operative 50% offset rule for every acquisition.','How can offset policy be judged by capability rather than nominal contract value?',p='P2')
add('Polity & Governance','05 · Rights, identity and public institutions','Internet shutdowns: necessity, reasons and less restrictive options','The July compilation discusses internet restrictions during protest-related public-order concerns.','The reviewed legal setting is the Telecommunications Act2023 and Temporary Suspension Rules2024.|Reasoned orders, necessity, proportionality, publication and limited duration/area are central safeguards.|Anuradha Bhasin links speech and professional activity through the internet with Article19 protections; indefinite suspension is impermissible.','A restriction on the medium affects several underlying rights. Public emergency/safety predicates and a permissible statutory purpose must be examined rather than treating any protest as sufficient ground.','Shutdowns can affect emergency information, digital payments, education and media verification.|Consider targeted lawful alternatives and rapid independent review; assess actual necessity instead of assuming a whole district must lose connectivity.|For AP, multilingual public orders and continuity plans for hospitals and welfare payments improve accountability.','The compilation is secondary evidence; volatile shutdown counts and exact order-authority timelines were not independently revalidated here. No unlimited standalone constitutional internet right is asserted.','Apply a proportionality test to communications restrictions.',src='DRISHTI')
add('Polity & Governance','05 · Rights, identity and public institutions','Fair-trial safeguards: a retrial is not an acquittal','Drishti discusses Abdul Hameed and deficient legal representation in a capital case.','The compilation reports that the death sentence was set aside and a fresh trial ordered.|Effective legal representation must be meaningful, not a nominal advocate appointment.|A co-accused confession cannot replace independent admissible evidence in the manner criticised by the Court.','Articles21 and22(1) protect fair procedure and legal representation; Article39A directs equal access to justice. Legal aid is an institutional obligation, not charity.','Serious accusations do not remove procedural safeguards; errors can harm victims’ interests as well as the accused by undermining a sustainable verdict.|Ensure counsel preparation, access to records, interpretation and judicial checks before important evidence stages.|For AP legal-services institutions, assess quality and continuity of representation alongside beneficiary numbers.','The judgment itself was not independently read. Setting aside a sentence with retrial does not establish acquittal or factual innocence.','Why is effective legal aid essential to legitimate criminal adjudication?',src='DRISHTI',p='P2')
add('Polity & Governance','05 · Rights, identity and public institutions','Citizenship determination: remand, notice and reasoned findings','The compilation reviews Sabitri Dey-related proceedings and procedural fairness in foreigner-status adjudication.','It reports the Supreme Court set aside High Court decisions and directed fresh adjudication.|Notice, opportunity to respond and reasoned evaluation are central to a lawful determination.|A failure of procedure can require reconsideration without itself establishing citizenship.','Articles5–11 address citizenship at constitutional commencement and Parliament’s power; the Citizenship Act supplies subsequent acquisition rules. Those categories must not be collapsed into one blanket birth rule.','Identity-document inconsistencies need contextual verification and accessible hearings, particularly for vulnerable residents.|A rule-of-law approach distinguishes citizenship, residence, migration status and administrative identity documents.|Avoid replacing one oversimplification with another: a remand is neither automatic citizenship nor confirmation of the earlier adverse finding.','The original judgment and exact affected-case count were not independently inspected. Do not infer Aadhaar or a birth certificate conclusively determines citizenship.','Explain procedural fairness as a safeguard in high-stakes identity adjudication.',src='DRISHTI',p='P2')
add('Polity & Governance','05 · Rights, identity and public institutions','CRS: completeness, timeliness and cause-of-death quality','The July compilation discusses the Civil Registration System report for reference year2024.','CRS continuously records births, deaths and stillbirths under the registration law.|It is administered through the Registrar General’s framework, with decentralised registration machinery.|A registered death need not have a medically certified cause, and registration can occur late.','CRS is a continuous administrative system; SRS is a sample-based demographic estimation system. A ratio to estimated events depends on the quality of both numerator and denominator.','High headline completeness can coexist with rural under-registration or poor infant-death reporting.|Track timely registration, disaggregation, cause certification and correction quality rather than celebrating one percentage.|AP local bodies and health facilities can improve linkage while protecting personal information and assisted access.','The source’s precise 2024 completeness percentages were not checked against the original report; they are not promoted as certified recall figures here. A 2024 report is not a count of July2026 events.','How should vital-statistics quality be evaluated beyond total registration?',src='DRISHTI',p='P2')
add('Society & Welfare','04 · Education and health evidence','UDISE+ and PGI: inputs, enrolment and learning are different','The compilation links school-management data with performance grading.','UDISE+ is a school-education management information system.|PGI combines multiple domains rather than measuring only enrolment or buildings.|Access, transition, retention, pupil–teacher ratios and learning outcomes answer different questions.','Gross enrolment can include pupils outside the official age group; retention/dropout need cohort and stage definitions. A favourable average pupil–teacher ratio can conceal single-teacher schools.','Compare administrative data with appropriate learning assessments and school-level validation.|Accessible toilets, ramps, functioning internet and teacher deployment matter more than a facility tick-box alone.|For AP, examine tribal access, disability inclusion, language support and secondary transition; do not invent a state rank from national headlines.','The original 2025–26 tables were not independently read; precise magazine percentages/rankings are withheld pending primary checks.','Design a district education dashboard that links resources to equitable learning.',src='DRISHTI',p='P2')
add('Economy','06 · New statistical series','Core industries: the nine-sector rebasing claim needs a vintage label','The July compilation discusses an ICI series using base2022–23.','It reports adding iron ore to the earlier eight-sector basket.|The compiling institution is the Office of Economic Adviser under DPIIT, distinct from MoSPI’s IIP compilation.|Sector weights and coverage differ across old and new bases; the compilation describes a raw-coal measure intended to avoid double counting.','An index’s base, basket, weights and deflator/data source must be read together. A new numerical index level cannot be spliced directly onto an old series without the documented linking method.','Rebasing can better represent current production but may change apparent sector contributions.|Record publication date, reference month and revision status separately; a strong low-weight sector may not dominate aggregate growth.|AP industrial answers should use consistent vintages rather than combining old eight-sector weights with a nine-sector headline.','Original OEA release not independently inspected; precise weights, linking factor and June growth are withheld from certified factual recall.','Explain how rebasing changes interpretation without necessarily changing underlying factory output.',src='DRISHTI',p='P2')
add('Economy','06 · New statistical series','Services-production trial index: volume is not nominal turnover','Drishti contains both a launch preview and a later trial-release account.','The compilation describes a formal-market services indicator with base2024–25.|The trial account refers to nineteen sub-sectors, with a composite overall index to follow.|Administrative/GST information and deflation are used; government/non-market and informal services are outside the described coverage.','Real output attempts to remove price effects from nominal values. A monthly production index is not identical to quarterly services GVA, and exclusions limit economy-wide inference.','Services measurement improves timeliness, but turnover can reflect prices, formalisation and reporting changes as well as volume.|Appropriate sector-specific proxies, revisions and documented weights are essential.|AP tourism/transport analysis should triangulate activity quantities with prices and avoid assigning the national formal-sector index to the whole state service economy.','Do not merge the preview’s tentative launch language with the later trial as one final comprehensive release. Primary methodology and exact release date remain unverified.','Assess the opportunities and limitations of a formal-services volume indicator.',src='DRISHTI',p='P2')
add('Economy','07 · Patient capital and circular industry','NIIF: sovereign anchoring and commercially managed investment','The compilation discusses an additional government commitment to NIIF.','NIIF is a sovereign-anchored platform intended to mobilise long-term institutional capital.|The magazine reports an additional ₹30,000 crore Union commitment, taking the stated total to ₹60,000 crore.|A commitment, a fund’s target corpus and money invested in completed infrastructure are distinct.','An investment fund is not the same as a ministry grant account or RBI reserves. Risk-adjusted commercial returns, project cash flows and investor rights shape its operation.','Public anchoring may crowd in patient capital but should not conceal project risk or contingent support.|Governance, independent investment decisions and transparent portfolio reporting protect credibility.|For AP infrastructure, project preparation and revenue viability matter; national fund commitments do not imply automatic state allocations.','The original Cabinet/fund release was not independently read. Amounts are attributed magazine claims; no completed disbursement or guaranteed return is certified.','Evaluate sovereign-anchored funds as a route to infrastructure finance.',src='DRISHTI',p='P2')
add('Environment','03 · Circular industry and biodiversity','Ship recycling: circular material flows need safe dismantling','The July compilation links recycling capability with India’s shipbuilding ambitions.','Recycling recovers steel and other materials from end-of-life vessels.|The Recycling of Ships Act2019 and Hong Kong Convention form part of the reviewed safety/environmental framework.|Hazardous-material identification, worker protection and waste management are distinct from gross-tonnage recycling capacity.','Gross tonnage, deadweight and light-displacement tonnage measure different things; a recycling ranking cannot be directly equated with shipbuilding output or export capability.','Recovered materials can support circular industry, but unsafe beaching, toxic exposure and downstream waste can transfer costs to workers and coastal communities.|Independent yard audits and traceable hazardous-waste disposal complement investment.|AP maritime development should distinguish building, repairing, operating and dismantling ships rather than label them one capability.','Precise global shares and the magazine’s mega-yard/job targets were not independently verified; an ambition is not a commissioned facility.','How can circular maritime industry reconcile competitiveness with worker and coastal safety?',src='DRISHTI',p='P2')
add('Science & Technology','02 · Precision and strategic technologies','Helium: cryogenic utility and concentrated supply','The compilation discusses helium-supply concerns and technological dependence.','Helium is an inert, non-flammable noble gas with a boiling point around4.2K.|Terrestrial helium accumulates over geological timescales, commonly in natural-gas systems, largely from radioactive decay.|Cryogenics, MRI, semiconductor processes and research depend on its physical properties.','Cosmic abundance does not imply inexpensive recoverable terrestrial supply. A gas reserve, concentration suitable for recovery and a commercial purification facility are different.','Recovery/recycling, leak control, supplier diversification and strategic inventory can reduce vulnerability.|Cryogenic transport and boil-off create logistical constraints not solved simply by finding trace helium.|The Krishna–Godavari basin is a relevant AP resource context, but no commercial helium discovery or proven recovery economics is inferred.','The magazine’s China export-ban claim and exact Indian import shares were not independently checked; they are not treated as verified policy facts.','Assess helium security as a link between science infrastructure and resource policy.',src='DRISHTI',p='P2')
add('Environment','02 · Energy transition and resource security','Puga geothermal wells: demonstration is not national-scale generation','The compilation discusses wells supporting a proposed1MW demonstration at Puga Valley, Ladakh.','Puga is a Himalayan geothermal setting, not a volcanic power station already supplying all Ladakh.|Geothermal systems use subsurface heat for power or direct heat applications.|Exploration wells, sustainable production flow and a commissioned electricity plant are different milestones.','Power conversion depends on temperature, flow and reservoir characteristics; lower-temperature direct use differs from steam-driven electricity. Renewable classification does not remove local reservoir-depletion risks.','Assess reinjection, corrosive fluids, induced seismicity, local ecology and high-altitude construction costs.|Reliable output requires measured reservoir performance, not merely a high temperature at one depth.|Use the pilot as a lesson in staged technology validation; no implication that AP has identical geological potential is made.','Well commissioning is not proof the full pilot plant is operational or national geothermal potential has become installed capacity.','How should geothermal demonstration projects be evaluated before scale-up?',src='DRISHTI',p='P2')
add('Science & Technology','02 · Precision and strategic technologies','White Rabbit timing: traceable time as critical infrastructure','Drishti describes an IST-dissemination demonstration centred on RRSL Bengaluru.','White Rabbit extends precision timing over optical-fibre Ethernet using Precision Time Protocol concepts.|The demonstration links precise Indian time dissemination with CSIR-NPL and institutional partners.|Finance, telecommunications, smart grids and digital records require consistent, traceable timestamps.','IST is UTC+5:30. Maintaining a national time standard, distributing it and synchronising a user’s device are separate technical functions. This is time transfer, not a change of India’s time zone.','Fibre-based timing can reduce dependence on vulnerable satellite signals, but route outages, hardware compromise and calibration remain risks.|Secure authentication, redundancy and auditable clock performance are important for trustworthy digital infrastructure.|For AP financial/industrial systems, resilience requires diverse timing paths rather than declaring one demonstration immune to spoofing.','A pilot does not establish universal national rollout, perfect security or that ordinary internet connections provide nanosecond accuracy.','Explain precision timing as a public-good infrastructure for the digital economy.',src='DRISHTI',p='P2')
add('Science & Technology','03 · Space and biomedical research','Space oncology: a research platform, not a cancer cure','The July compilation examines microgravity-based studies of tumour behaviour and therapies.','Microgravity can alter cell adhesion, signalling and three-dimensional cell-culture behaviour.|Spheroids and protein-crystallisation studies may support disease models and drug development.|Laboratory response does not establish clinical efficacy, population benefit or an approved treatment.','Microgravity changes the effective experimental environment; it does not remove gravity from the universe. Simulated microgravity and actual spaceflight also require careful comparison.','Translational value depends on reproducibility, controls, radiation confounders and affordable downstream therapy.|Hospitals, laboratories and space agencies need ethical review, transparent data and realistic opportunity-cost analysis.|For India, collaboration should target answerable biomedical questions rather than use space novelty as evidence of medical success.','A change in cancer cells in an experimental setting is not proof astronauts or terrestrial patients can be cured by microgravity.','Evaluate the promise and limits of space-based biomedical research.',src='DRISHTI',p='P2')
add('Science & Technology','03 · Space and biomedical research','Gaganyaan re-entry: a chain of safety-critical systems','The compilation reviews crew-module preparation and safe return requirements.','Thermal protection manages intense aerodynamic heating during atmospheric re-entry.|Attitude-control systems orient the module; parachutes slow it for sea recovery.|Flotation/up-righting and communication support crew safety after splashdown.','A blunt-body detached shockwave and an ablative heat shield perform different protective roles. A drogue parachute stabilises; main parachutes provide substantial final deceleration.','A human-spaceflight safety case must cover separation, re-entry, descent, splashdown and recovery as a connected system.|Redundancy helps only if common-mode failures and integration are tested.|Indian Navy recovery coordination and realistic sea conditions matter; a component test is not a completed crewed mission.','Preparations and test success do not certify that astronauts flew in July or establish a final mission date.','Why must human-spaceflight progress be judged by integrated safety evidence?',src='DRISHTI',p='P2')
add('Society & Welfare','04 · Education and health evidence','NeoSep1: local evidence for resistant neonatal infections','The compilation reports Indian enrolment at JIPMER in an international antibiotic-combination trial.','NeoSep1 investigates safe/effective treatment combinations for severe resistant infections in young infants.|It is a multicentre trial associated with GARDP, not an already approved universal antibiotic regimen.|Randomisation, eligibility and monitoring are essential to interpretable comparative evidence.','The neonatal period conventionally covers the first28 completed days; a study including infants up to90days does not redefine every young-infant infection as strictly neonatal. AMR can vary greatly by hospital and region.','Local pathogen surveillance and culture/susceptibility testing improve clinical relevance.|Antibiotic stewardship, infection prevention and timely clinical care remain necessary alongside research.|AP neonatal units should use approved clinical guidance and ethical trial processes, not copy experimental combinations from a current-affairs note.','Trial enrolment is not proof a combination is effective or licensed. Unverified magazine death counts are withheld.','Explain why locally relevant trials and infection prevention must advance together.',src='DRISHTI',p='P2')
add('Science & Technology','02 · Precision and strategic technologies','Quantum error correction: logical reliability, not magic parallel answers','The compilation links error-correction progress with India’s quantum ambitions.','Physical qubits are vulnerable to noise and decoherence.|Error-correcting codes encode logical information across multiple physical qubits and use suitable checks to detect/correct errors.|Below-threshold physical performance can allow lower logical error rates as appropriate code resources grow.','Superposition does not permit reading all possible answers at once; measurement and algorithm design constrain accessible information. Entanglement does not enable faster-than-light messaging.','Useful fault-tolerant computing needs hardware, control, software, benchmarking and a large resource overhead.|Compare logical error rates and demonstrated workloads, not only raw physical-qubit count.|For AP Quantum Valley study, national mission targets and state land/institutional announcements are not proof of a functioning universal fault-tolerant computer.','Quantum devices are not automatically faster for every task, and not every qubit platform operates at the same cryogenic temperature.','What evidence should distinguish quantum capability from headline qubit counts?',src='DRISHTI')
add('Environment','03 · Circular industry and biodiversity','White-bellied heron: river connectivity and riparian habitat','Drishti discusses hydropower-related concerns in the Lohit river landscape.','The white-bellied heron is a highly threatened eastern-Himalayan river-associated bird.|The compilation identifies free-flowing rivers and mature riparian trees as important habitat.|Changes in flow, turbidity, disturbance and nesting sites can affect ecological suitability.','A riverine bird depends on habitat quality across connected reaches, not just the number of hectares inside a protected-area boundary. Project-level mitigation and basin-level cumulative effects differ.','Assess environmental flows, seasonal breeding needs and upstream/downstream impacts before considering compensation planting adequate.|Long-term monitoring needs consistent survey methods and protection against disclosure of sensitive nest locations.|AP answers can transfer the habitat-connectivity principle to river and wetland management without claiming this Himalayan species is an established AP population.','Exact global/Indian population estimates and schedules were not independently verified here; avoid presenting small fluctuating counts as permanent facts.','How should river-development appraisal account for narrowly distributed threatened species?',src='DRISHTI',p='P2')
add('Environment','03 · Circular industry and biodiversity','Biogas and CBG: circularity depends on methane control','The compilation discusses biological conversion of organic waste into useful energy and manure.','Anaerobic digestion produces methane-rich biogas from suitable organic feedstock.|Upgrading removes unwanted components to produce compressed biogas meeting the applicable quality requirements.|Digestate can return nutrients to soils when properly processed and used.','Raw biogas, upgraded biomethane/CBG and natural gas are related fuels, not identical product specifications. Organic origin does not make unmanaged methane leakage harmless.','Reliable feedstock contracts, segregation, collection logistics and off-take are crucial to project viability.|Methane leakage, digestate contamination and process energy can weaken promised climate benefits.|AP dairy, food-waste and crop-residue opportunities need local mass/energy balances and farmer incentives rather than assuming every residue is freely available.','A theoretical national resource estimate is not installed capacity; avoid a blanket claim every biogas project is carbon-neutral.','Design a lifecycle-based assessment of a decentralised CBG project.',src='DRISHTI',p='P2')
add('Culture & History','01 · Modern thought and public service','Vivekananda: service, universalism and national regeneration','The July compilation recalls Vivekananda on his4July death anniversary.','Born Narendra Nath Datta in1863, he was a disciple of Ramakrishna.|His1893 Chicago address and Vedanta/Yoga engagement connected Indian thought to international audiences.|The Ramakrishna Mission was founded in1897 with a strong service orientation.','Religious universalism, social service and modern nationalism overlap but are not identical ideas. A historical thinker’s influence should be located in nineteenth-century colonial society.','Use education, dignity and service as interpretive themes, with specific institutions and works rather than motivational quotations of uncertain origin.|Public-service ethics can connect care for vulnerable people with practical institutional action.|Avoid treating one thinker as the sole cause of independence or erasing internal diversity in Indian reform traditions.','An anniversary is not a new historical discovery. Different Ramakrishna institutions and their founding dates should not be casually conflated.','Discuss the relation between spiritual universalism and social service in Vivekananda’s thought.',src='DRISHTI',day=4,p='P2')
add('Andhra Pradesh','01 · Industry and women’s enterprise','Hero parts centre: separate ₹750 crore facility from wider expansion','The1July foundation ceremony was reported by ETV Bharat on2July.','The Global Parts Center2.0 carries a reported ₹750 crore investment and approximately85,000sqm built-up scale.|The site described as Madanapalle is in Satyavedu mandal, Tirupati district, not the better-known Madanapalle town.|A separate ₹3,200 crore five-year expansion plan and additional employment expectations were announced.','A parts distribution/after-sales hub, vehicle assembly capacity and EV-component manufacturing are related but distinct operations. Foundation, construction and commercial operation are different milestones.','AP’s connectivity and supplier ecosystem can support industrial logistics, but investment announcements need milestone and employment verification.|Track local procurement, women’s safe employment, technical training and actual additional jobs.|The report gives inconsistent existing-capacity figures; avoid building a growth calculation from them.','Do not add the₹750crore and₹3,200crore as proved non-overlapping disbursements or call projected jobs already created.','Assess industrial-investment announcements through location accuracy and measurable additionality.',src='HERO',day=1,ap=True)
add('Andhra Pradesh','01 · Industry and women’s enterprise','Union Bank SHG charges: reduced fees are not a loan waiver','ETV Bharat reported the decision concerning women’s self-help groups on1July.','The reported waiver concerns processing and inspection charges on SHG lending.|Previously specified cash-credit loans above₹10lakh attracted processing fees, while loans above₹5lakh attracted quarterly inspection charges.|The decision does not, in the reviewed account, waive principal or all interest on SHG borrowing.','The effective cost of credit includes interest, fees, insurance and transaction costs. A fee waiver is different from subsidised interest, repayment moratorium or debt cancellation.','Lower charges can improve working capital, but viable enterprise also needs market access, financial literacy and protection from coercive recovery.|SERP and bank coordination should verify charges actually removed from statements and enable complaints.|The report’s headline savings example requires fee-frequency/tax assumptions not fully reconciled here, so exact claimed savings are withheld.','The original bank circular was not read; do not generalise this reported Union Bank decision to all banks and all women’s loans.','How should AP evaluate financial inclusion beyond the amount of SHG credit sanctioned?',src='SHG',day=1,ap=True)
add('Andhra Pradesh','02 · Tribal inclusion and disability rights','412 Aadhaar centres: compliance action and continuity of access','A2July Telugu report describes alleged irregularities at tribal-welfare enrolment centres.','The report identifies412 centres under the Tribal Welfare Department.|The headline uses cancellation, but quoted officials describe temporary suspension pending correction and compliant kits.|Allegations include documentation, agency-management and operating-location problems; the original UIDAI order was not inspected.','Aadhaar enrolment, citizenship and entitlement eligibility are different issues. An agency-level suspension does not cancel every resident’s Aadhaar or prove beneficiaries committed fraud.','Corrective action should secure enrolment while providing alternative access for remote tribal residents.|Audit operator credentials, devices, consent and document checks, with independent grievance support.|Continuity plans are essential where identity enrolment affects access to welfare; punish proven wrongdoing without treating an entire community as suspect.','Do not report a permanent shutdown or final criminal guilt from the headline alone; the duration and remedial conditions remain source-limited.','Balance enrolment integrity with inclusion in tribal areas.',src='AADHAAR',day=2,precision='reporting-day',ap=True)
add('Andhra Pradesh','02 · Tribal inclusion and disability rights','Rare diseases and disability certificates: progression needs reassessment','The Hindu’s2July report documents certification barriers in Vijayawada and Kurnool-related cases.','The report includes a child with Becker muscular dystrophy whose assessed percentage remained unchanged despite deterioration.|Another family sought certification for a progressive Huntington’s-disease case, with delays after assessment.|SADAREM appointment/assessment processes and limited certifier awareness emerge as implementation concerns.','A rare-disease diagnosis and a legally assessed disability percentage are not the same determination. Progressive functional loss requires appropriate, evidence-based reassessment, not solely recognition of a disease name.','Use trained multidisciplinary assessment, accessible appointments, reasoned decisions and time-bound appeals.|Support caregivers and home-bound patients instead of forcing repeated travel to demonstrate visible impairment.|Pension bands in the report are examples, not a fully verified current eligibility schedule; assistance must follow the governing rules and individual assessment.','Neither every rare condition automatically establishes a fixed disability percentage nor an old certificate proves the condition cannot worsen.','How can disability administration become responsive to progressive diseases?',src='DISABILITY',day=2,precision='reporting-day',ap=True)
add('Andhra Pradesh','03 · Health-policy participation','Rare-disease policy dialogue: July publication, June consultation','IORD published a stakeholder account on7July; its photo caption dates the conference24June.','The consultation was organised through DME at Dr.NTR University of Health Sciences, Vijayawada.|Participants discussed early diagnosis, genetic testing, provider training and coordination with patient organisations.|The account supports a policy-development process, not proof that a final enforceable state policy was notified in July.','National policy direction and state service delivery are complementary. A stakeholder conference, draft consultation, Cabinet decision and notified scheme are different stages.','Patient registries need consent, privacy and a useful referral pathway rather than data collection without treatment access.|Transparent eligibility, financing and priorities help balance expensive therapies with diagnosis, supportive care and prevention.|Advocacy accounts are valuable for lived experience but first-state and universal-treatment claims require independent verification.','Do not date the actual conference7July or promise every proposed referral centre/free treatment service already operates.','Design a participatory and financially accountable state rare-disease framework.',src='RARE,DISABILITY',day=7,precision='reporting-day',ap=True,p='P2')
add('Andhra Pradesh','04 · Tourism, heritage and urban resilience','NiVU tourism MoU: multilingual access with a phased rollout','Deccan Chronicle reports the7July tourism partnership with Explurger.','The pact is for three years, with30major destinations planned in the first year and over100in the wider rollout.|QR access supports voice/text in more than130languages without a separate visitor app, according to the report.|Mangalagiri temple pilots precede the wider plan; tourist analytics are part of the proposed service.','AI-enabled interpretation, physical accessibility and heritage authenticity are different components of visitor experience. An MoU and a pilot do not establish statewide implementation.','Curated local-language knowledge, source attribution and expert review can reduce hallucinated history and misleading ritual information.|Minimise personal data, explain analytics and provide alternatives for visitors without phones/connectivity.|Measure reliable answers, accessibility and user benefit, not only QR scans. The contemporary report names Explurger; a coaching source’s Xplorer label is not adopted.','The first-AI-tourism-state claim is promotional/aspirational, not an independently audited national ranking or completed deployment.','What safeguards should govern AI interpretation at AP heritage and pilgrimage sites?',src='NIVU',day=7,ap=True)
add('Andhra Pradesh','04 · Tourism, heritage and urban resilience','Godavari Pushkaralu2027 works: sanction, finance and lasting services','A4July report describes preparations in Rajamahendravaram for the2027 event.','The minister announced₹580crore first-phase support, using both released and sanctioned language.|The report cites₹1,500crore proposals and₹150crore state share within the allocation.|Roads, drainage, drinking water, sanitation, ghats and river-pollution control feature in the proposed works.','Proposal cost, administrative sanction, actual release and expenditure are distinct public-finance stages. A state share within a package is not an additional package to add again.','Permanent urban benefits should outlast the festival: sewage treatment, safe access and maintained water services matter.|Coordinate municipal, irrigation, endowment, transport and emergency-response agencies with accountable milestones.|Underlying orders and bank flows remain unread; the story is not an expenditure audit or proof all funds reached contractors.','Do not add580,150and1500crore into a fictitious total. July preparation is not the2027festival itself.','Evaluate pilgrimage investment through fiscal clarity, crowd safety and post-event public value.',src='PUSHKAR',day=4,precision='reporting-day',ap=True)
add('Andhra Pradesh','05 · Prices, employment and resource planning','AP inflation in the13July release: June prices, provisional estimates','MoSPI’s primary release reports Andhra Pradesh alongside national state-level comparisons.','AP combined headline CPI inflation for June2026 is5.39%; CFPI food inflation is8.18%.|The all-India combined figures are4.38% and5.32% respectively.|The series uses2024=100; these are year-on-year inflation rates, not index levels or month-on-month price changes.','A state rate reflects its consumption basket and observed price changes; it is not an estimate for every household. Higher food inflation can disproportionately affect poorer families.','Investigate crop supply, perishables, transport and retail conditions before attributing the gap to a single policy.|Use targeted relief and supply-chain improvements while avoiding claims that one state number proves general price-control success or failure.|State item indices can have thin samples; MoSPI explicitly advises caution. Updated final estimates may differ.','13July is publication date, not the reference month. Do not label5.39% as July AP inflation or compare it to a quarterly average without explanation.','Explain how AP can respond to food-price pressure using appropriately dated evidence.',src='CPI',day=13,ap=True)
add('Andhra Pradesh','05 · Prices, employment and resource planning','AP reservoir-solar appraisal: a national eligibility opportunity','The31July floating-solar approval creates a national policy context; this is an AP application note, not a project sanction.','The national target is5,000MW with co-located storage of at least two hours.|Post-commissioning assistance and separate preparatory-study support follow different conditions.|All states/UTs may benefit, but no named AP reservoir allocation is established by the inspected release.','Reservoir ownership, irrigation operations, fisheries rights, power evacuation and environmental appraisal can involve different institutions. Solar surface-area availability must be tested against seasonal water levels.','Map drawdown, anchoring, dam-safety restrictions and fishers’ access before issuing tenders.|Assess storage safety and grid value against added capital cost, while consulting local water users.|Tie public support to verified commissioning and ecological/service performance, not merely installed floats or signed intent letters.','Do not turn this analytical opportunity into a news claim that an AP reservoir already received5000MW or₹5070crore.','Propose a screening framework for floating solar on AP reservoirs.',src='SOLAR',day=31,ap=True,p='P2')
add('Andhra Pradesh','05 · Prices, employment and resource planning','Krishna–Godavari offshore context: security with coastal safeguards','Samudra Manthan provides a31July national exploration context; AP-specific implications here are analytical.','The scheme supports geological data, offshore exploratory drilling and common infrastructure.|Seismic indications are not equivalent to commercially recoverable reserves.|The inspected approval does not assign a quantified new production outcome or reserve discovery to AP.','Offshore resources require coordination of petroleum regulation, maritime safety, environment and coastal livelihoods. Reserve accretion and annual production use different concepts.','Protect navigation and fishers’ access through consultation, credible spill response and liability arrangements.|Assess shared evacuation infrastructure and local supplier/skill opportunities without assuming drilling necessarily succeeds.|Use project-specific EIA and cumulative coastal planning; a national energy-security objective does not eliminate statutory clearances.','Do not mislabel a national outlay as AP investment already spent, or confuse exploration licensing with permission to ignore marine safeguards.','Evaluate offshore-energy opportunities from the perspective of AP’s coastal communities.',src='OFFSHORE',day=31,ap=True,p='P2')
add('Andhra Pradesh','05 · Prices, employment and resource planning','Rural-employment transition in AP: a household-facing audit','The July national payment/transition rules have direct state administrative implications; this is not an independent audit of AP implementation.','Old admissible liabilities up to30June require verification and reconciliation.|Verified work records/cards and ongoing works can continue under the transition arrangements.|A household’s remaining financial-year days must account for days already availed, while wages and unemployment allowance follow different payment responsibilities.','A launch ceremony, notified entitlement and actual household work delivered are separate. Person-days measure labour time, not the number of permanent jobs created.','At village level, publish accessible work-demand receipts, days used/balance and outstanding-payment status.|Check rejected bank transactions and eKYC problems through assisted mechanisms rather than silently removing workers.|Social audits should reconcile financial records with worker testimony and physical assets, including transferred assets and ongoing works.','No state-specific₹300wage-floor or125freshdays is certified from the national payment rules alone; exact entitlements require the relevant statute/notifications.','How should AP make a statutory employment transition visible and accountable to workers?',src='TRANSITION,WAGES',day=1,ap=True)
add('Andhra Pradesh','04 · Tourism, heritage and urban resilience','Seshachalam epigraphy: a July revision topic, not a July discovery','The July magazine includes inscriptions independently reported on23June; the inscribed date is31July1554.','The accounts describe three inscriptions associated with Sadasivaraya at Sadasivakona in Tirupati’s Seshachalam forest.|Telugu,Tamil and Kannada attest a multilingual epigraphic setting.|Temple/monastery patronage, revenue arrangements and Gudimallam links inform the regional historical interpretation.','The date of an inscription, modern discovery, news publication and magazine indexing are four separate chronology fields. Sadasivaraya should not be casually substituted with Krishnadevaraya.','Estampages, documented transcription and contextual interpretation support preservation and future verification.|Forest access and heritage protection require coordinated permission, minimal disturbance and responsible tourism.|Avoid deriving a complete picture of social life from a single royal grant or repeating an unverified earliest-Siva-temple superlative.','31July1554 is not a2026discovery date. This note is July-indexed revision; the original news was in June, even outside the magazine’s stated25June start.','What can multilingual temple inscriptions reveal, and what are their limits as historical evidence?',src='DRISHTI,HERITAGE',ap=True,p='P2')
add('Economy','06 · New statistical series','National CPI release: monthly rates versus quarterly averages','The13July release provides primary evidence for June inflation.','All-India combined CPI inflation is4.38% year-on-year, provisional.|CFPI inflation is5.32%, with rural/urban CPI4.74%/3.92%.|The release uses base2024=100; May’s final combined CPI rate is3.93%.','An inflation rate is the percentage change in an index over a specified comparison period. A slower increase is disinflation, not necessarily falling prices; an index level of107 is not107%inflation.','Food shocks can influence household expectations and real incomes while requiring supply responses as well as monetary analysis.|Separate commodity-specific volatility from broad persistent pressure and consider distributional burdens.|Do not compare PRS’s Q1average directly with this monthly rate as if both describe the same time aggregation.','These are June prices published in July, not July reference-month inflation or a confirmed full-year forecast.','Use dated CPI evidence to distinguish price levels, rates and policy trade-offs.',src='CPI',day=13)
add('Economy','08 · Skill finance','Skill-credit guarantee: individual cover and portfolio cap differ','The modified scheme was notified9July; selected Gazette opening provisions and PRS were inspected.','Eligible collateral-free skill loans span₹5,000–₹7.5lakh, subject to scheme conditions.|PRS describes75%default cover up to₹4lakh and70%above₹4lakh up to₹7.5lakh, with aggregate claims capped at15%of relevant annual disbursement.|The revised framework includes qualifying non-NSQF courses via SIDH-registered providers and differentiated six/twelve-month lock-in periods.','A credit guarantee shares lender default risk; it is not a scholarship, borrower debt waiver or assurance every application is approved. The portfolio payout ceiling and per-borrower guarantee percentage operate at different levels.','Access gains require reliable training quality, placement evidence and responsible affordability assessment.|The upper limit already appeared in the2024revision; avoid claiming the full increase first occurred only in July2026.|Use grievance and outcome monitoring to prevent low-quality providers selling debt-funded courses without employable skills.','The15%cap is not15%individual cover. Lock-in expiry does not itself make a claim payable; other default/recovery conditions remain.','How can skill-loan guarantees expand access without financing poor-quality training?',src='SKILL,PRS',day=9)
for country,title,facts,analysis,trap in [
('Japan','Economic-security cooperation: resilient supply chains, not autarky','PRS records MoCs involving biogas, batteries, pharmaceuticals, critical minerals and AI policy.|A joint economic-security declaration emphasises project-based collaboration in strategic sectors.|The review also describes research and infrastructure cooperation.','Diversification and trusted partnerships can reduce single-source risk but may raise cost or exclude suppliers.|India should assess joint R&D, local capability, interoperable standards and project implementation rather than count MoUs as operating factories.','The review’s exact visit/outcome dates conflict; no precise day is assigned. Signing a cooperation text is not a new binding mutual-defence alliance.'),
('Indonesia','Maritime and technology ties: cooperation across the eastern Indian Ocean','PRS reports cooperation on peaceful space use and maritime security.|The account includes medical products, disaster management and mineral/steel supply chains.|Rare-earth magnets and defence-industrial cooperation feature among the reported areas.','Indonesia’s archipelagic geography makes maritime domain awareness and resilient sea lanes important.|Technology collaboration needs export permissions, procurement decisions and real transfer/absorption; discussion of a system does not establish a completed sale.','Prabowo Subianto is Indonesia’s President, not Prime Minister as the review incorrectly labels him. No completed BrahMos delivery is inferred.'),
('Australia','Energy, maritime and emerging-technology cooperation','The review records declarations on energy security, maritime/defence, cyber/critical technologies and sports.|MoUs include maritime law enforcement and skill development in mining.|Research, emerging-technology skills and cinema cooperation also appear.','Resource supply and workforce capability can support strategic resilience without eliminating price, environmental or geopolitical risks.|Distinguish bilateral cooperation from Quad functions and identify the concrete delivery institutions behind declarations.','A declaration is not proof of an operating mine, a military basing agreement or a guaranteed uranium shipment.'),
('New Zealand','Maritime cooperation, Antarctic research and trade ambitions','PRS reports logistics-support, hydrographic-data and maritime cooperation arrangements.|The account includes Antarctic research, academic mobility, disaster risk and dairying.|Doubling bilateral trade by2030is a target, not an achieved trade value.','Hydrographic data support navigation, while Antarctic research relates to scientific/environmental cooperation, not sovereignty over Antarctica.|Agricultural productivity and mobility cooperation need standards, safeguards and evidence of implementation rather than automatic market-access assumptions.','A logistics agreement is not a permanent base or a mutual-defence treaty; a trade target is not an implemented free-trade concession.')]:
 add('International Relations','01 · Bilateral cooperation and economic security',country+' · '+title,'The July policy review records bilateral engagements; this note uses month-level indexing and attributes the outcomes to PRS.',facts,'A declaration, MoU, sector agreement and enforceable domestic implementation have different legal and operational consequences.',analysis+'|For AP, use ports, skills, agri-food and technology links as possible applications, not unverified state-specific agreements.',trap,'Assess '+country+' cooperation through strategic objectives, delivery mechanisms and implementation limits.',p='P2')
# Correct chronology on the separately reported executive directive.
J[4]['why']+=' PRS bibliography dates the underlying directive30June; it is included here as July-reviewed follow-through, not a newly dated July order.'
assert len(J)==69,len(J)
N+=J
for p,o in [('data/notes.json',N),('data/sources.json',S),('data/source-access.json',A)]: (R/p).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
print('Authored',len(J),'July notes;',len(N),'archive;',len(S),'references')
